def bfs(start_i, start_j, n, m, grid, visited):
    cells = deque()
    cells.append((start_i, start_j))
    visited[start_i][start_j] = True
    min_i = min_j = n
    max_i = max_j = -1

    while cells:
        i, j = cells.popleft()
        min_i = min(min_i, i)
        min_j = min(min_j, j)
        max_i = max(max_i, i)
        max_j = max(max_j, j)

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and not visited[ni][nj]:
                visited[ni][nj] = True
                cells.append((ni, nj))

