        # Precompute forward fibonacci sums for range queries
        self.f_front = [0] * (n + 5)
        self.f_front[1] = 1
        self.f_front[2] = 2
        for i in range(3, n + 5):
            self.f_front[i] = (self.f_front[i - 1] + self.f_front[i - 2]) % mod

        # Precompute backward fibonacci sums for lazy propagation
