            l, r = idx * 2, idx * 2 + 1
            lz = self.lazy[idx]
            val_contrib = (lz * (self.fib[1] + self.fib[0])) % mod

            self.left[l] = (self.left[l] + lz * val_contrib) % mod
            self.lazy[l] = (self.lazy[l] + lz) % mod

            self.left[r] = (self.left[r] + lz * val_contrib) % mod
            self.lazy[r] = (self.lazy[r] + lz) % mod

            self.lazy[idx] = 0

    def update_point(self, p, val):
        self.update(1, 1, self.size, p, val)

    def update(self, idx, l, r, p, add):
        if r < p or l > p:
            return
        if l == r:
            self.left[idx] = (self.left[idx] - self.left[idx] % mod + add) % mod
            self.lazy[idx] = add
            return

        idx = idx
        if l == r or add == 0:
            return

        self.push(idx)
        mid = (l + r) // 2

        self.update(idx * 2, l, mid, p, add)
        self.update(idx * 2 + 1, mid + 1, r, p, add)

        self.left[idx] = (self.left[idx * 2] + self.left[idx * 2 + 1]) % mod

