    if m == 0:
        return "YES\n"

    # Build implication graph for 2-SAT
    # Node 2*i represents ¬x_i, Node 2*i+1 represents x_i
    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]

    def lit_idx(lit):
        idx = abs(lit) - 1
        return 2 * idx + (0 if lit < 0 else 1)

    # Add implication: ¬l -> (other literals) for each clause
    for clause in clauses:
        for i, lit in enumerate(clause):
            u = lit_idx(lit) ^ 1  # negation
            for j, lit_j in enumerate(clause):
                if i != j:
                    w = lit_idx(lit_j) ^ 1
                    adj[u].append(w)

    # Tarjan's SCC algorithm
    state = [0] * num_nodes  # 0=white, 1=gray, 2=black
    indices = [0] * num_nodes
    lowlinks = [0] * num_nodes
    stack = []
    on_stack = [False] * num_nodes
    scc_id = [0] * num_nodes
    timer = [0]
    scc_count = [0]

    def dfs(v):
        state[v] = 1
        indices[v] = lowlinks[v] = timer[0]
        timer[0] += 1
        stack.append(v)
        on_stack[v] = True

        for w in adj[v]:
            if state[w] == 0:
                dfs(w)
                lowlinks[v] = min(lowlinks[v], lowlinks[w])
            elif state[w] == 1:
                lowlinks[v] = min(lowlinks[v], indices[w])

        if lowlinks[v] == indices[v]:
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc_id[w] = scc_count[0]
                if w == v:
                    break
            scc_count[0] += 1

    for v in range(num_nodes):
        if state[v] == 0:
            dfs(v)

    # Check if satisfiable
    sat = True
    for i in range(m):
        if scc_id[2 * i] == scc_id[2 * i + 1]:
            sat = False
            break

    if not sat:
        return "NO"

    # Get assignment (pick max literal per variable in lexicographic order)
    assignment = [False] * m
    for i in range(m):
        if scc_id[2 * i + 1] >= scc_id[2 * i]:
            assignment[i] = True

    result = "YES\n" + "".join(map(str, assignment))
    return result

