def nCr_mod(n, r, p):
    """Computes C(n, r) mod p efficiently using Wilson's theorem"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1

    # Precompute factorials and inverse factorials up to n
    # For large n and small r or r near n, use direct computation
    if r < p // 2 and n - r < p // 2:
        # Direct computation with modular inverse
        numerator = 1
        for i in range(n - r + 1, n + 1):
            numerator = (numerator * i) % p
        denominator = 1
        for i in range(1, r + 1):
            denominator = (denominator * i) % p
        return (numerator * pow(denominator, p - 2, p)) % p
    else:
        # General case - need precomputation
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = (fact[i - 1] * i) % p

        inv = [1] * (n + 1)
        inv[n] = pow(fact[n], p - 2, p)
        for i in range(n - 1, -1, -1):
            inv[i] = (inv[i + 1] * (i + 1)) % p

        return (fact[n] * inv[r] % p * inv[n - r] % p) % p

def valid_sequences(a, b, p):
    """Count valid sequences with a notes and b debts using reflection principle"""
    if a < b:
        return 0
    total = nCr_mod(a + b, a, p)
    invalid = nCr_mod(a + b, a + 1, p)
    return (total - invalid + p) % p

